{"command": "python3 <<'PY'
import subprocess, os, tempfile

def run_timeout(args, timeout=2):
    p=subprocess.Popen(["./executable"]+args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, stdin=subprocess.PIPE, text=True)
    try:
        out,err=p.communicate(input="", timeout=timeout)
        return ("exit",p.returncode,out,err)
    except subprocess.TimeoutExpired:
        p.kill()
        try:
            out,err=p.communicate(timeout=2)
        except: out,err="",""
        return ("timeout",None,out or "",err or "")

def test(args_list):
    import tempfile
    with tempfile.NamedTemporaryFile(mode='w', delete=False, suffix='.ini') as f:
        f.write("log-dir-path=/tmp\n")
        fname=f.name
    for args in args_list:
        if "--config" not in args and "-c" not in args:
            full=["--config",fname]+args
        else:
            full=args
        res=run_timeout(full, timeout=2)
        print(f"args {full} => {res[0]} code={res[1]} out={repr(res[2][:500])} err={repr(res[3][:1000])}")
    os.unlink(fname)

test([
 ["--sunday-start=false"],
 ["--sunday-start","false"],
 ["--first-line-section=false"],
 ["--password",""],
])

# extra positional with valid config
import tempfile
with tempfile.NamedTemporaryFile(mode='w', delete=False, suffix='.ini') as f:
    f.write("log-dir-path=/tmp\n")
    fname=f.name
for extra in [["pos1"], ["--log-dir-path","/tmp","pos1"]]:
    res=run_timeout(["--config",fname]+extra, timeout=2)
    print(f"extra {extra} => {res[0]} code={res[1]} out={repr(res[2][:500])} err={repr(res[3][:500])}")
os.unlink(fname)
PY"}

