import subprocess
pt_hex="41"*16
ct_hex="cc2fa9048948451f553f32d6c1dbff5c"
open("/tmp/ct.bin",'wb').write(bytes.fromhex(ct_hex))
pw=b"secret"
for key_len in [16,24,32]:
    key=pw.ljust(key_len, b'\x00')
    key_hex=key.hex()
    print(f"trying padded key len {key_len} hex {key_hex}")
    for mode in ["aes-128-cfb","aes-192-cfb","aes-256-cfb","aes-128-cbc","aes-256-cbc","aes-128-ctr","aes-256-ctr","aes-128-ofb","aes-256-ofb","aes-128-ecb","aes-256-ecb"]:
        parts=mode.split("-")
        bits=parts[1]  # 128 etc
        exp={"128":32,"192":48,"256":64}[bits]
        if len(key_hex)!=exp:
            continue
        if "ecb" in mode:
            cmd=["openssl","enc","-d",f"-{mode}","-K",key_hex,"-in","/tmp/ct.bin"]
            p=subprocess.run(cmd, capture_output=True)
            if p.stdout.hex()=="41"*16:
                print(f"SUCCESS {key_hex} {mode}")
        else:
            for iv in ["00"*16]:
                cmd=["openssl","enc","-d",f"-{mode}","-K",key_hex,"-iv",iv,"-in","/tmp/ct.bin"]
                p=subprocess.run(cmd, capture_output=True)
                if p.stdout.hex()=="41"*16:
                    print(f"SUCCESS {key_hex} {mode} {iv}")
print("done")
PY"}

