    if bits==128:
        return h[:32]
    else:
        # need 64 hex, if h shorter, repeat?
        if len(h)>=64:
            return h[:64]
        else:
            return (h*4)[:64]

for k_algo in algos:
    for k_bits in [128,256]:
        k_hex=get_key(hashes[k_algo], k_bits)
        mode=f"aes-{k_bits}-ecb"
        for iv_algo in list(hashes.keys()):
            iv_hex=hashes[iv_algo][:32]
